import type { WoolyGuideAccess } from "./wooly-page-guides";
import { woolyTaskDetails } from "./wooly-task-details";

export interface WoolyKnowledgeEntry {
  readonly id: string;
  readonly feature: string;
  readonly title: string;
  readonly answer: string;
  readonly steps: readonly string[];
  readonly variants: readonly [string, string, string, string];
  readonly keywords: string;
  readonly access: WoolyGuideAccess;
  readonly route: string;
  readonly target: string;
  readonly tutorial: boolean;
  readonly purpose: string;
  readonly prerequisites?: string;
  readonly stepTargets?: readonly string[];
  readonly stepRoutes?: readonly string[];
  readonly surface?: string;
  /** Source evidence kept with the catalog so coverage documentation can be audited. */
  readonly evidence: string;
}

interface Feature {
  readonly group: string;
  readonly route: string;
  readonly target: string;
  readonly access: WoolyGuideAccess;
  readonly evidence: string;
}

type RecordInput = readonly [
  id: string,
  question: string,
  answer: string,
  action: string,
  success: string,
  variants: readonly [string, string, string, string],
  keywords: string,
  purpose: string,
  tutorial?: boolean,
  target?: string,
  route?: string,
  surface?: string,
  access?: WoolyGuideAccess,
  taskSteps?: readonly string[],
  prerequisites?: string,
  stepTargets?: readonly string[],
];

function entries(feature: Feature, records: readonly RecordInput[]): WoolyKnowledgeEntry[] {
  return records.map(([id, title, answer, action, success, variants, keywords, purpose, tutorial = true, target, route, surface, access, taskSteps, prerequisites, stepTargets]) => {
    const resolvedTarget = target ?? feature.target;
    const steps = taskSteps ?? splitActions(action, success);
    const popupTarget = surface ? surfaceTarget(surface) : null;
    return {
      id,
      feature: feature.group,
      title,
      answer,
      steps,
      variants,
      keywords,
      access: access ?? feature.access,
      route: route ?? routeOverrides[id] ?? feature.route,
      target: resolvedTarget,
      tutorial,
      purpose,
      evidence: feature.evidence,
      ...(prerequisites ? { prerequisites } : {}),
      ...(surface ? { surface } : {}),
      ...(stepTargets ? { stepTargets } : surface ? { stepTargets: steps.map((_, index) => index === 0 ? resolvedTarget : popupTarget ?? resolvedTarget) } : {}),
      ...(stepRoutesById[id] ? { stepRoutes: stepRoutesById[id] } : {}),
      ...woolyTaskDetails[id],
    };
  });
}

function surfaceTarget(surface: string): string | null {
  const targets: Readonly<Record<string, string>> = {
    announcement: "notice-form",
    reminder: "notice-form",
    "save-template": "template-form",
    "template-picker": "template-picker-form",
    "band-notes": "band-notes-form",
    arrangement: "arrangement-form",
    member: "member-drawer",
    "member-drawer": "member-drawer",
    "song-delete": "song-delete-dialog",
    "event-delete": "event-delete-dialog",
  };
  return targets[surface] ?? null;
}

